    function __ESBMC_assume(bool) internal pure {}
    function run(uint depositAmount, uint minSum, uint withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount < minSum);
        require(withdrawAmount > depositAmount);
        c.SetLogFile(address(0)); if (__ESBMC_reverted()) return;
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        uint recordedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint ethBefore = address(c).balance;
        bool reverted;
        c.Collect(withdrawAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted
            && c.balances(address(this)) == recordedBefore
            && address(c).balance == ethBefore);
    }
    receive() external payable {}
