pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmount, uint256 minSum, uint256 withdrawAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount < minSum);
        vm.assume(withdrawAmount > depositAmount);
        try c.SetLogFile(address(0)) {} catch { return; }
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint256 recordedBefore;
        try c.balances(address(this)) returns (uint256 __r) { recordedBefore = __r; } catch { return; }
        uint ethBefore = address(c).balance;
        bool reverted;
        try c.Collect(withdrawAmount) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted
            && c.balances(address(this)) == recordedBefore
            && address(c).balance == ethBefore);
    }

    function testFuzz_run(uint256 depositAmount, uint256 minSum, uint256 withdrawAmount) public {
        _run(depositAmount, minSum, withdrawAmount);
    }

    receive() external payable {}
}
